import type { Metadata, Viewport } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import {
  SurfaceProvider,
  surfaceBootstrapScript,
} from "@/lib/surface/SurfaceProvider";
import { SiteFooter } from "@/components/ui/SiteFooter";
import "./globals.css";

const geistSans = Geist({ variable: "--font-geist-sans", subsets: ["latin"] });
const geistMono = Geist_Mono({ variable: "--font-geist-mono", subsets: ["latin"] });

export const metadata: Metadata = {
  title: "FTC Team Hub",
  description:
    "Season registration, roster, calendar, announcements, and engineering notebook for FIRST Tech Challenge teams.",
};

export const viewport: Viewport = {
  themeColor: "#14161A",
  // Designed at 380px and scaled up. Students are on phones.
  width: "device-width",
  initialScale: 1,
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en"
      data-surface-mode="glass"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
      suppressHydrationWarning
    >
      <head>
        {/* Applies the persisted competition-mode choice before first paint,
            so a user who enabled it doesn't see a flash of glass. */}
        <script dangerouslySetInnerHTML={{ __html: surfaceBootstrapScript }} />
      </head>
      <body className="min-h-full flex flex-col">
        <SurfaceProvider>
          <div className="flex-1">{children}</div>
          <SiteFooter />
        </SurfaceProvider>
      </body>
    </html>
  );
}
